import { safeFetch } from './scripts/identity_check.mjs';
const noValidate = async () => {};
const types = new Set(['text/html']);
const total = 3 * 1024 * 1024;
let produced = 0;
const stream = new ReadableStream({
  pull(controller) {
    if (produced >= total) { controller.close(); return; }
    const chunk = new Uint8Array(64 * 1024);
    produced += chunk.length;
    controller.enqueue(chunk);
  },
});
const fakeFetch = async () => new Response(stream, { headers: { 'content-type': 'text/html' } });
try {
  await safeFetch('https://example.com/', 1000, types, fakeFetch, noValidate);
  console.log(JSON.stringify({ status: 'ok' }));
} catch (error) {
  console.log(JSON.stringify({ status: 'unsafe', reason: error.reason, bytes_read: produced, total }));
}
